/**
 * Deployment-reported identity: the values the verified lock env handed this process, not an
 * observation of the container. <code>commit</code> and <code>image</code> are absent outside a lock-driven
 * deployment.
 */
export const zRunningRelease = z.object({
    channel: z.enum([
        'RELEASE',
        'COMMIT',
        'DEVELOPMENT'
    ]),
    commit: z.string().optional(),
    environment: z.string(),
    image: z.string().optional(),
    roles: z.array(z.enum([
        'SERVER',
        'WORKER',
        'WEBHOOK'
    ])),
    version: z.string()
});

/**
 * The running release and what the last update check found. Discovery is advisory: nothing here
 * verifies an artifact or performs an upgrade.
 */
export const zReleaseStatus = z.object({
    failure: z.enum([
        'RATE_LIMITED',
        'UNAVAILABLE',
        'MALFORMED'
    ]).optional(),
    history: z.array(zReleaseStart),
    lastAttempt: z.iso.datetime({ offset: true }).pipe(z.coerce.date()).optional(),
    lastSuccess: z.iso.datetime({ offset: true }).pipe(z.coerce.date()).optional(),
    latest: zLatestRelease.optional(),
    nextCheck: z.iso.datetime({ offset: true }).pipe(z.coerce.date()).optional(),
    retryUntil: z.iso.datetime({ offset: true }).pipe(z.coerce.date()).optional(),
    running: zRunningRelease,
    runningSince: z.iso.datetime({ offset: true }).pipe(z.coerce.date()).optional(),
    status: z.enum([
        'DISABLED',
        'NOT_APPLICABLE',
        'NEVER_CHECKED',
        'CURRENT',
        'UPDATE_AVAILABLE',
        'FAILED'
    ])
});

