export const zScanReportProblemsPage = z.object({
    content: z.array(zScanReportProblem),
    hasNext: z.boolean(),
    nextCursor: z.string().nullable()
});

/**
 * The activity on one pull request or issue in a time range
 */
export const zActivityWork = z.object({
    actions: z.array(zActivityAction),
    id: z.string(),
    lastOccurredAt: z.iso.datetime({ offset: true }).pipe(z.coerce.date()),
    people: z.array(zUserInfo),
    work: z.lazy((): any => zWorkItem).optional()
});

/**
 * One page of activity grouped by the pull request or issue it happened on, latest first
 */
export const zActivityWorkPage = z.object({
    content: z.array(zActivityWork),
    nextCursor: z.string().optional()
});

/**
 * Information about a label from a repository
 */
export const zLabelInfo = z.object({
    color: z.string(),
    id: z.int(),
    name: z.string(),
    repository: z.lazy((): any => zRepositoryInfo).optional()
});

/**
 * What is open for one member right now
 */
export const zOpenWork = z.object({
    issues: z.lazy((): any => zWorkItemList),
    pullRequests: z.lazy((): any => zWorkItemList),
    reviewRequests: z.lazy((): any => zWorkItemList),
    teamReviewRequests: z.lazy((): any => zWorkItemList)
});

/**
 * Information about a git repository
 */
export const zRepositoryInfo = z.object({
    description: z.string().optional(),
    hiddenFromContributions: z.boolean(),
    htmlUrl: z.string(),
    id: z.int(),
    labels: z.array(zLabelInfo).optional(),
    name: z.string(),
    nameWithOwner: z.string()
});

/**
 * Detailed information about a team including members, repositories, and labels
 */
export const zTeamInfo = z.object({
    description: z.string().optional(),
    hidden: z.boolean(),
    htmlUrl: z.string().optional(),
    id: z.int(),
    labels: z.array(zLabelInfo),
    members: z.array(zUserInfo),
    membershipCount: z.int().min(-2147483648, { error: 'Invalid value: Expected int32 to be >= -2147483648' }).max(2147483647, { error: 'Invalid value: Expected int32 to be <= 2147483647' }),
    name: z.string(),
    organization: z.string().optional(),
    parentId: z.int().optional(),
    privacy: z.enum(['SECRET', 'VISIBLE']).optional(),
    repoPermissionCount: z.int().min(-2147483648, { error: 'Invalid value: Expected int32 to be >= -2147483648' }).max(2147483647, { error: 'Invalid value: Expected int32 to be <= 2147483647' }),
    repositories: z.array(zRepositoryInfo),
    slug: z.string()
});

/**
 * A pull request or issue
 */
export const zWorkItem = z.object({
    author: zUserInfo.optional(),
    checks: z.enum([
        'SUCCESS',
        'FAILURE',
        'PENDING',
        'CANCELLED',
        'NONE',
        'NO_PIPELINE',
        'SKIPPED'
    ]).optional(),
    createdAt: z.iso.datetime({ offset: true }).pipe(z.coerce.date()).optional(),
    htmlUrl: z.string().optional(),
    id: z.int(),
    isDraft: z.boolean(),
    number: z.int().min(-2147483648, { error: 'Invalid value: Expected int32 to be >= -2147483648' }).max(2147483647, { error: 'Invalid value: Expected int32 to be <= 2147483647' }),
    repository: zRepositoryInfo.optional(),
    requestedTeams: z.array(zTeamRef).optional(),
    reviewDecision: z.enum([
        'APPROVED',
        'CHANGES_REQUESTED',
        'REVIEW_REQUIRED'
    ]).optional(),
    reviewers: z.array(zReviewer).optional(),
    state: z.enum([
        'OPEN',
        'CLOSED',
        'MERGED'
    ]),
    title: z.string(),
    type: z.enum(['PULL_REQUEST', 'ISSUE']),
    updatedAt: z.iso.datetime({ offset: true }).pipe(z.coerce.date()).optional()
});

/**
 * Pull requests or issues, most recently updated first, up to a limit
 */
export const zWorkItemList = z.object({
    content: z.array(zWorkItem),
    hasMore: z.boolean()
});
